:root {
  --bg: #1f2937;
  --card: #f9fafb;
  --ink: #111827;
  --muted: #4b5563;
  --accent: #f59e0b;
  --accent-dark: #b45309;
  --hunger: #ef4444;
  --happiness: #10b981;
  --energy: #3b82f6;
  --focus: #2563eb;
}

* {
  box-sizing: border-box;
}

html, body {
  margin: 0;
  min-height: 100%;
}

body {
  min-height: 100vh;
  display: grid;
  place-items: center;
  padding: 16px;
  background: radial-gradient(circle at top, #374151 0%, var(--bg) 60%);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, Arial, sans-serif;
  font-size: 16px;
  color: var(--ink);
}

.card {
  width: min(100%, 420px);
  background: var(--card);
  border-radius: 24px;
  padding: 24px;
  box-shadow: 0 20px 40px rgba(0, 0, 0, 0.35);
  display: flex;
  flex-direction: column;
  gap: 20px;
}

h1 {
  margin: 0;
  text-align: center;
  font-size: 1.6rem;
  letter-spacing: 0.02em;
}

.pet-stage {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
  padding: 16px 0;
  background: linear-gradient(180deg, #e0f2fe 0%, #f0f9ff 100%);
  border-radius: 18px;
}

.pet {
  width: 140px;
  height: 140px;
  position: relative;
  animation: bob 2.4s ease-in-out infinite;
}

@keyframes bob {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-6px); }
}

.pet-body {
  position: absolute;
  inset: 0;
  background: #fbbf24;
  border-radius: 40% 40% 45% 45%;
  box-shadow: inset -10px -10px 0 rgba(0, 0, 0, 0.08);
}

.pet-ear {
  position: absolute;
  width: 34px;
  height: 34px;
  background: #f59e0b;
  border-radius: 8px 8px 0 0;
  top: -16px;
}

.pet-ear.left { left: 16px; transform: rotate(-12deg); }
.pet-ear.right { right: 16px; transform: rotate(12deg); }

.pet-face {
  position: absolute;
  inset: 0;
}

.pet-eye {
  position: absolute;
  width: 16px;
  height: 20px;
  background: #111827;
  border-radius: 50%;
  top: 50px;
}

.pet-eye.left { left: 36px; }
.pet-eye.right { right: 36px; }

.pet-eye::after {
  content: "";
  position: absolute;
  width: 6px;
  height: 6px;
  background: #fff;
  border-radius: 50%;
  top: 3px;
  left: 3px;
}

.pet-mouth {
  position: absolute;
  width: 28px;
  height: 14px;
  border-bottom: 4px solid #111827;
  border-radius: 0 0 20px 20px;
  left: 50%;
  transform: translateX(-50%);
  top: 82px;
}

.pet-cheek {
  position: absolute;
  width: 14px;
  height: 8px;
  background: rgba(239, 68, 68, 0.45);
  border-radius: 50%;
  top: 80px;
}

.pet-cheek.left { left: 22px; }
.pet-cheek.right { right: 22px; }

.mood {
  margin: 0;
  font-weight: 700;
  font-size: 1.1rem;
  color: var(--accent-dark);
}

.stats {
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.stat-head {
  display: flex;
  justify-content: space-between;
  font-weight: 600;
  margin-bottom: 6px;
  color: var(--muted);
}

.bar {
  height: 16px;
  background: #e5e7eb;
  border-radius: 999px;
  overflow: hidden;
}

.bar-fill {
  height: 100%;
  width: 70%;
  border-radius: 999px;
  transition: width 0.35s ease;
}

.bar-fill.hunger { background: var(--hunger); }
.bar-fill.happiness { background: var(--happiness); }
.bar-fill.energy { background: var(--energy); }

.controls {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
}

.btn {
  font: inherit;
  font-weight: 700;
  padding: 12px 8px;
  border: 2px solid transparent;
  border-radius: 12px;
  color: #fff;
  cursor: pointer;
  transition: transform 0.1s ease, filter 0.15s ease, box-shadow 0.15s ease;
}

.btn.feed { background: var(--hunger); }
.btn.play { background: var(--happiness); }
.btn.sleep { background: var(--energy); }

.btn:hover { filter: brightness(1.1); }
.btn:active { transform: translateY(2px); }

.btn:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
  box-shadow: 0 0 0 4px #fff;
}

@media (max-width: 360px) {
  .card { padding: 18px; }
  .pet { width: 120px; height: 120px; }
  .pet-eye.left { left: 28px; }
  .pet-eye.right { right: 28px; }
  .pet-eye { top: 42px; }
  .pet-mouth { top: 70px; }
  .pet-cheek { top: 68px; }
}

(function () {
  "use strict";

  var state = {
    hunger: 70,
    happiness: 70,
    energy: 70
  };

  var els = {
    hungerFill: document.getElementById("hunger-fill"),
    happinessFill: document.getElementById("happiness-fill"),
    energyFill: document.getElementById("energy-fill"),
    hungerValue: document.getElementById("hunger-value"),
    happinessValue: document.getElementById("happiness-value"),
    energyValue: document.getElementById("energy-value"),
    hungerBar: document.getElementById("hunger-bar"),
    happinessBar: document.getElementById("happiness-bar"),
    energyBar: document.getElementById("energy-bar"),
    mood: document.getElementById("mood"),
    pet: document.getElementById("pet")
  };

  function clamp(n) {
    return Math.max(0, Math.min(100, n));
  }

  function moodFor() {
    var h = state.hunger;
    var p = state.happiness;
    var e = state.energy;

    if (h < 25) return "Hungry";
    if (e < 25) return "Tired";
    if (p < 25) return "Sad";
    if (h > 80 && p > 80 && e > 80) return "Ecstatic";
    if (h > 60 && p > 60 && e > 60) return "Happy";
    return "Okay";
  }

  function render() {
    els.hungerFill.style.width = state.hunger + "%";
    els.happinessFill.style.width = state.happiness + "%";
    els.energyFill.style.width = state.energy + "%";

    els.hungerValue.textContent = state.hunger;
    els.happinessValue.textContent = state.happiness;
    els.energyValue.textContent = state.energy;

    els.hungerBar.setAttribute("aria-valuenow", String(state.hunger));
    els.happinessBar.setAttribute("aria-valuenow", String(state.happiness));
    els.energyBar.setAttribute("aria-valuenow", String(state.energy));

    var mood = moodFor();
    els.mood.textContent = mood;
    els.pet.setAttribute("aria-label", "Pixel pet looking " + mood.toLowerCase());
  }

  function act(fn) {
    fn();
    state.hunger = clamp(state.hunger);
    state.happiness = clamp(state.happiness);
    state.energy = clamp(state.energy);
    render();
  }

  document.getElementById("feed").addEventListener("click", function () {
    act(function () {
      state.hunger += 20;
      state.happiness += 4;
      state.energy -= 3;
    });
  });

  document.getElementById("play").addEventListener("click", function () {
    act(function () {
      state.happiness += 18;
      state.energy -= 12;
      state.hunger -= 6;
    });
  });

  document.getElementById("sleep").addEventListener("click", function () {
    act(function () {
      state.energy += 25;
      state.hunger -= 5;
      state.happiness += 2;
    });
  });

  render();
})();
